/bin/bash -lc "PYTHONPATH=lib:test/units python - <<'PY'
from ansible.utils import encrypt
for ident in ('2','2a','2y','2b'):
    try:
        print(ident, encrypt.CryptHash('bcrypt').hash('foo', salt='123456789012345678901u', rounds=4, ident=ident)[:7])
    except Exception as e:
        print(ident, type(e).__name__, str(e))
PY"

